package io.jooby.internal.utow;

import io.jooby.ByteRange;
import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.StandardOpenOption;

import static org.mockito.Mockito.when;

public class UtowContextsend_HttpServerExchangegetRequestHeadersFikaTest {

    @Test
    public void testSendFileChannelTriggersGetRequestHeaders() throws IOException {
        // Create mock HttpServerExchange
        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);

        // Create mock Router
        Router router = Mockito.mock(Router.class);

        // Create real UtowContext instance
        UtowContext context = new UtowContext(exchange, router);

        // Setup exchange to return a Range header
        HeaderMap requestHeaders = new HeaderMap();
        requestHeaders.put(Headers.RANGE, "bytes=0-100");
        when(exchange.getRequestHeaders()).thenReturn(requestHeaders);

        // Setup exchange response headers
        HeaderMap responseHeaders = new HeaderMap();
        when(exchange.getResponseHeaders()).thenReturn(responseHeaders);

        // Create a real FileChannel from a temporary file
        File tempFile = File.createTempFile("test", ".txt");
        tempFile.deleteOnExit();

        // Write some data to the file
        java.nio.file.Files.write(tempFile.toPath(), "Test content for file channel".getBytes());

        try (FileChannel fileChannel = FileChannel.open(tempFile.toPath(), StandardOpenOption.READ)) {
            // Call the entry point method
            context.send(fileChannel);
        }
    }
}

