    @Test
    public void testOnErrorCallsIoUtilsSafeClose() throws Exception {
        // Create mocks for constructor dependencies
        UtowContext mockCtx = Mockito.mock(UtowContext.class);
        WebSocketChannel mockChannel = Mockito.mock(WebSocketChannel.class);
        Router mockRouter = Mockito.mock(Router.class);
        Logger mockLogger = Mockito.mock(Logger.class);
        Config mockConfig = Mockito.mock(Config.class);

        // Setup mock behavior
        Mockito.when(mockCtx.getRouter()).thenReturn(mockRouter);
        Mockito.when(mockRouter.getLog()).thenReturn(mockLogger);
        Mockito.when(mockRouter.getConfig()).thenReturn(mockConfig);
        Mockito.when(mockConfig.hasPath(Mockito.anyString())).thenReturn(false);

        // Create instance using the provided constructor
        UtowWebSocket instance = new UtowWebSocket(mockCtx, mockChannel);

        // Create a throwable to pass as parameter
        Throwable throwable = new RuntimeException("Test error");

        // Call the entry point method
        instance.onError(mockChannel, null, throwable);

        // The test will execute the method chain but we need to trigger
        // the path that leads to IoUtils.safeClose
        // Based on the provided method sources, we need to trigger handleClose
        // which calls sendClose with a callback that uses IoUtils.safeClose

        // We need to set up the instance to be in a state where handleClose
        // will call sendClose with the callback containing IoUtils.safeClose

        // First, set the instance as open so handleClose will execute the sendClose path
        java.lang.reflect.Field openField = UtowWebSocket.class.getDeclaredField("open");
        openField.setAccessible(true);
        ((java.util.concurrent.atomic.AtomicBoolean) openField.get(instance)).set(true);

        // Create a mock WebSocketCloseStatus
        io.jooby.WebSocketCloseStatus closeStatus = io.jooby.WebSocketCloseStatus.NORMAL;

        // Use reflection to call handleClose since it's private
        java.lang.reflect.Method handleCloseMethod = UtowWebSocket.class.getDeclaredMethod(
            "handleClose", io.jooby.WebSocketCloseStatus.class);
        handleCloseMethod.setAccessible(true);

        // This should trigger the callback chain that includes IoUtils.safeClose
        handleCloseMethod.invoke(instance, closeStatus);
    }
}

