package io.jooby.internal.utow;

import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.ServerConnection;
import io.undertow.util.HeaderMap;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.nio.channels.ReadableByteChannel;

public class UtowContextsend_HttpServerExchangegetRequestContentLengthFikaTest {

    @Test
    public void testSendCallsGetRequestContentLength() throws Exception {
        // Create mock exchange with necessary behavior
        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);

        // Setup response headers to avoid chunked encoding
        HeaderMap responseHeaders = new HeaderMap();
        Mockito.when(exchange.getResponseHeaders()).thenReturn(responseHeaders);

        // Add CONTENT_LENGTH header to prevent chunked encoding
        responseHeaders.put(io.undertow.util.Headers.CONTENT_LENGTH, "100");

        // Setup getRequestContentLength to return a value
        Mockito.when(exchange.getRequestContentLength()).thenReturn(100L);

        // Create mock ServerConnection to avoid NPE in UtowChunkedStream
        ServerConnection connection = Mockito.mock(ServerConnection.class);
        Mockito.when(exchange.getConnection()).thenReturn(connection);

        // Create mock router
        Router router = Mockito.mock(Router.class);

        // Create instance using constructor
        UtowContext context = new UtowContext(exchange, router);

        // Create mock channel
        ReadableByteChannel channel = Mockito.mock(ReadableByteChannel.class);

        // Call entry point method
        context.send(channel);
    }
}

