        open.set(true);
        addSession(this);
        Config conf = ctx.getRouter().getConfig();
        long timeout = (conf.hasPath("websocket.idleTimeout")) ? conf.getDuration("websocket.idleTimeout", TimeUnit.MILLISECONDS) : TimeUnit.MINUTES.toMillis(5);
        if (timeout > 0) {
            channel.setIdleTimeout(timeout);
        }
