private void dispatch(Runnable runnable) {
    if (dispatch) {
        ctx.getRouter().getWorker().execute(runnable);
    } else {
        runnable.run();
    }
}

void fireConnect() {
    // fire only once
    try {
        open.set(true);
        addSession(this);
        Config conf = ctx.getRouter().getConfig();
        long timeout = (conf.hasPath("websocket.idleTimeout")) ? conf.getDuration("websocket.idleTimeout", TimeUnit.MILLISECONDS) : TimeUnit.MINUTES.toMillis(5);
        if (timeout > 0) {
            channel.setIdleTimeout(timeout);
        }
        if (onConnectCallback != null) {
            dispatch(webSocketTask(() -> onConnectCallback.onConnect(this), true));
        } else {
            ready.countDown();
        }
        channel.getReceiveSetter().set(this);
        channel.resumeReceives();
    } catch (Throwable x) {
        onError(channel, x);
    }
}

private void handleClose(WebSocketCloseStatus status) {
    OnClose callback = onCloseCallback.getAndSet(null);
    if (isOpen()) {
        open.set(false);
        // close socket:
        sendClose(status.getCode(), status.getReason(), channel, new WebSocketCallback<UtowWebSocket>() {
            @Override
