        } else {
            ready.countDown();
        }
        channel.getReceiveSetter().set(this);
        channel.resumeReceives();
    } catch (Throwable x) {
        onError(channel, x);
    }
}

private void handleClose(WebSocketCloseStatus status) {
    OnClose callback = onCloseCallback.getAndSet(null);
    if (isOpen()) {
        open.set(false);
        // close socket:
        sendClose(status.getCode(), status.getReason(), channel, new WebSocketCallback<UtowWebSocket>() {
            @Override
            public void onError(final WebSocketChannel channel, final UtowWebSocket ws, final Throwable throwable) {
                IoUtils.safeClose(channel);
                ws.onError(channel, throwable);
            }

            @Override
            public void complete(final WebSocketChannel channel, final UtowWebSocket ws) {
                IoUtils.safeClose(channel);
            }
        }, this);
