import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.ReadableByteChannel;

public class UtowChunkedStreamrun_IoCallbackonCompleteFikaTest {

    @Test
    public void test() throws IOException {
        long len = -1L;
        UtowChunkedStream stream = new UtowChunkedStream(len);

        ReadableByteChannel source = Mockito.mock(ReadableByteChannel.class);
        Mockito.when(source.read(Mockito.any(ByteBuffer.class))).thenReturn(-1);

        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);
        Sender sender = Mockito.mock(Sender.class);
        Mockito.when(exchange.getResponseSender()).thenReturn(sender);

        ServerConnection connection = Mockito.mock(ServerConnection.class);
        Mockito.when(exchange.getConnection()).thenReturn(connection);

        ByteBufferPool byteBufferPool = Mockito.mock(ByteBufferPool.class);
        Mockito.when(connection.getByteBufferPool()).thenReturn(byteBufferPool);

        PooledByteBuffer pooledByteBuffer = Mockito.mock(PooledByteBuffer.class);
        Mockito.when(byteBufferPool.allocate()).thenReturn(pooledByteBuffer);
        Mockito.when(pooledByteBuffer.getBuffer()).thenReturn(ByteBuffer.allocate(1024));

        IoCallback callback = Mockito.mock(IoCallback.class);

        stream.send(source, exchange, callback);
        stream.run();
    }
}

