package io.jooby.internal.utow;

import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class UtowHandlerhandleRequest_BuilderbuildFikaTest {

    @Test
    public void testHandleRequestInvokesBuilderBuild() throws Exception {
        Router router = Mockito.mock(Router.class);
        int bufferSize = 8192;
        long maxRequestSize = 1024 * 1024L;
        boolean defaultHeaders = false;

        UtowHandler handler = new UtowHandler(router, bufferSize, maxRequestSize, defaultHeaders);

        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);
        HeaderMap requestHeaders = new HeaderMap();
        HeaderMap responseHeaders = new HeaderMap();

        when(exchange.getRequestHeaders()).thenReturn(requestHeaders);
        when(exchange.getResponseHeaders()).thenReturn(responseHeaders);

        requestHeaders.put(Headers.CONTENT_TYPE, Headers.APPLICATION_X_WWW_FORM_URLENCODED);
        requestHeaders.put(Headers.CONTENT_LENGTH, "100");

        handler.handleRequest(exchange);
    }
}

