package io.jooby.internal.utow;

import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.nio.ByteBuffer;
import java.nio.channels.ReadableByteChannel;

public class UtowContextifSetChunked_HeaderMapputFikaTest2 {

    @Test
    public void testSendPath() throws Exception {
        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);
        Router router = Mockito.mock(Router.class);

        HeaderMap responseHeaders = new HeaderMap();
        Mockito.when(exchange.getResponseHeaders()).thenReturn(responseHeaders);

        UtowContext context = new UtowContext(exchange, router);

        ReadableByteChannel channel = new ReadableByteChannel() {
            private boolean open = true;

            public int read(ByteBuffer dst) {
                if (dst.hasRemaining()) {
                    dst.put((byte) 't');
                    dst.put((byte) 'e');
                    dst.put((byte) 's');
                    dst.put((byte) 't');
                    return 4;
                }
                return 0;
            }

            public boolean isOpen() {
                return open;
            }

            public void close() {
                open = false;
            }
        };

        context.send(channel);
    }
}

