package io.jooby.internal.utow;

import io.jooby.Router;
import io.jooby.Server;
import io.undertow.server.HttpServerExchange;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.mock;

public class UtowSender_UtowContextdestroy_HttpServerExchangeendExchangeFikaTest {

    @Test
    public void test() {
        HttpServerExchange exchange = mock(HttpServerExchange.class);
        Router router = mock(Router.class);
        UtowContext ctx = new UtowContext(router, exchange);
        UtowSender sender = new UtowSender(ctx, exchange);
        sender.close();
    }

    private static class UtowContext {
        private final Router router;
        private final HttpServerExchange exchange;

        UtowContext(Router router, HttpServerExchange exchange) {
            this.router = router;
            this.exchange = exchange;
        }

        void destroy(Exception cause) {
            try {
                if (cause != null) {
                    org.slf4j.Logger log = router.getLog();
                    if (Server.connectionLost(cause)) {
                        log.debug("exception found while sending response {} {}", getMethod(), getRequestPath(), cause);
                    } else {
                        log.error("exception found while sending response {} {}", getMethod(), getRequestPath(), cause);
                    }
                }
            } finally {
                this.exchange.endExchange();
            }
        }

        private String getMethod() {
            return "GET";
        }

        private String getRequestPath() {
            return "/test";
        }
    }
}

