package io.jooby.internal.utow;

import io.jooby.Formdata;
import io.jooby.Multipart;
import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.handlers.form.FormData;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class UtowContextformData_FormValuegetValueFikaTest {

    @Test
    public void testMultipartTriggersFormValueGetValue() {
        // Mock dependencies
        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);
        Router router = Mockito.mock(Router.class);

        // Create FormData with at least one non-file entry
        FormData formData = Mockito.mock(FormData.class);
        FormData.FormValue formValue = Mockito.mock(FormData.FormValue.class);

        // Setup iterator for form data keys
        java.util.Iterator<String> iterator = Mockito.mock(java.util.Iterator.class);
        when(iterator.hasNext()).thenReturn(true, false);
        when(iterator.next()).thenReturn("testKey");

        // Setup deque for form values
        java.util.Deque<FormData.FormValue> deque = new java.util.ArrayDeque<>();
        deque.add(formValue);

        // Configure mocks
        when(exchange.getAttachment(FormDataParser.FORM_DATA)).thenReturn(formData);
        when(formData.iterator()).thenReturn(iterator);
        when(formData.get("testKey")).thenReturn(deque);
        when(formValue.isFileItem()).thenReturn(false);
        when(formValue.getValue()).thenReturn("testValue");

        // Create instance using constructor
        UtowContext context = new UtowContext(exchange, router);

        // Invoke entry point
        context.multipart();
    }
}

