package io.jooby.internal.utow;

import io.jooby.Formdata;
import io.jooby.Multipart;
import io.jooby.Router;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.handlers.form.FormData;
import io.undertow.util.AttachmentKey;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class UtowContextformData_FormValueisFileItemFikaTest {

    @Test
    public void testMultipartToIsFileItem() {
        // Create mock HttpServerExchange
        HttpServerExchange exchange = Mockito.mock(HttpServerExchange.class);

        // Create mock Router
        Router router = Mockito.mock(Router.class);

        // Create FormData with at least one FormValue that will trigger isFileItem()
        FormData formData = new FormData(1024);
        FormData.FormValue formValue = Mockito.mock(FormData.FormValue.class);
        when(formValue.isFileItem()).thenReturn(true);
        formData.add("testField", formValue);

        // Create attachment key for FORM_DATA
        AttachmentKey<FormData> formDataKey = AttachmentKey.create(FormData.class);

        // Configure exchange to return our formData when FORM_DATA attachment is requested
        when(exchange.getAttachment(formDataKey)).thenReturn(formData);

        // Create UtowContext instance
        UtowContext context = new UtowContext(exchange, router);

        // Call the entry point method
        context.multipart();
    }
}

